#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

/* Provided by the candidate in solution.c */
int32_t interpolate_table(const int32_t *xs, const int32_t *ys, int32_t n, int32_t x);

int main(void)
{
    int32_t n;
    if (scanf("%" SCNd32, &n) != 1 || n < 2) {
        return 1;
    }

    int32_t *xs = malloc((size_t)n * sizeof *xs);
    int32_t *ys = malloc((size_t)n * sizeof *ys);
    if (xs == NULL || ys == NULL) {
        return 1;
    }
    for (int32_t i = 0; i < n; i++) {
        if (scanf("%" SCNd32, &xs[i]) != 1) {
            return 1;
        }
    }
    for (int32_t i = 0; i < n; i++) {
        if (scanf("%" SCNd32, &ys[i]) != 1) {
            return 1;
        }
    }

    int32_t x;
    while (scanf("%" SCNd32, &x) == 1) {
        printf("%" PRId32 "\n", interpolate_table(xs, ys, n, x));
    }

    free(xs);
    free(ys);
    return 0;
}
